/* part:page.style.kit.pagination */
/* Kit css: pagination    kit version 1.0.0    pairs with kit/pagination.js
   .kit-pg (the host; a size container; data-variant=full|compact|simple|load-more, data-unknown, data-links), .kit-pg-head (summary and tools),
   .kit-pg-sum (the range in words), .kit-pg-tools (.kit-pg-size, .kit-pg-jump), .kit-pg-nav > .kit-pg-list > .kit-pg-li (page boxes: .kit-pg-btn,
   .kit-pg-num, .kit-pg-cur, .kit-pg-dots, .kit-pg-arrow with .kit-pg-ico and .kit-pg-t), .kit-pg-pick (compact), data-long (five-digit pages), .kit-pg-err, .kit-pg-more (.kit-pg-bar, .kit-pg-moreb).
   State is shape as well as colour: the current page is filled, bold and underlined; a disabled arrow has a dashed outline; an error carries a "!" badge and a bar.
   Every page box is as wide as the widest page number (--kit-pg-d digits, set by the script), so the arrows never move while paging.
   Needs from the board: --panel --sunk --ink --ink-2 --ink-3 --rule --rule-2 --accent --accent-ink --accent-soft --danger --danger-soft --f-ui;
   optional --focus (the focus ring) and --pg-radius (corner radius, default 8px). */
.kit-pg { container-type: inline-size; display: grid; gap: 10px; min-width: 0; color: var(--ink); font: 14px/1.4 var(--f-ui); }
.kit-pg [hidden] { display: none !important; }
.kit-pg-sr { position: absolute !important; width: 1px; height: 1px; margin: -1px; padding: 0; overflow: hidden; clip: rect(0 0 0 0); clip-path: inset(50%); white-space: nowrap; border: 0; }
.kit-pg-head { display: flex; flex-wrap: wrap; align-items: center; justify-content: space-between; gap: 8px 16px; min-width: 0; }
.kit-pg-sum { margin: 0; min-width: 0; color: var(--ink-2); font-variant-numeric: tabular-nums; overflow-wrap: anywhere; }
.kit-pg-sum:focus { outline: none; }
.kit-pg-sum:focus-visible { outline: 2px solid var(--focus, var(--accent)); outline-offset: 2px; border-radius: 4px; }
.kit-pg-tools { display: flex; flex-wrap: wrap; align-items: center; gap: 8px 18px; min-width: 0; }
.kit-pg-size, .kit-pg-jump, .kit-pg-pickf { display: inline-flex; align-items: center; gap: 8px; margin: 0; min-width: 0; }
.kit-pg-lbl { color: var(--ink-2); font-size: 13px; white-space: nowrap; }
.kit-pg-select, .kit-pg-input { box-sizing: border-box; min-block-size: 36px; min-width: 0; padding: 4px 8px; border: 1px solid var(--rule-2); border-radius: var(--pg-radius, 8px); background: var(--panel); color: var(--ink); font: 500 14px/1.2 var(--f-ui); font-variant-numeric: tabular-nums; }
.kit-pg-select { padding-inline-end: 4px; cursor: pointer; }
.kit-pg-input { inline-size: calc(var(--kit-pg-d, 2) * 1ch + 30px); text-align: center; }
.kit-pg-input[aria-invalid="true"] { border: 2px solid var(--danger); }
.kit-pg-select:focus-visible, .kit-pg-input:focus-visible, .kit-pg-btn:focus-visible { outline: 2px solid var(--focus, var(--accent)); outline-offset: 2px; }
.kit-pg-err { display: flex; align-items: flex-start; gap: 8px; margin: 0; padding: 6px 10px; border-inline-start: 3px solid var(--danger); border-radius: 4px; background: var(--danger-soft); color: var(--ink); font-size: 13px; overflow-wrap: anywhere; }
.kit-pg-err:empty { display: none; }
.kit-pg-err::before { content: "!"; flex: none; display: inline-grid; place-items: center; inline-size: 1.3em; block-size: 1.3em; border-radius: 999px; background: var(--danger); color: var(--panel); font-weight: 700; line-height: 1; }
.kit-pg-nav { min-width: 0; }
.kit-pg-list { display: flex; flex-wrap: wrap; align-items: center; gap: 4px; margin: 0; padding: 0; list-style: none; }
.kit-pg-li { display: flex; margin: 0; }
.kit-pg-btn { box-sizing: border-box; position: relative; display: inline-flex; align-items: center; justify-content: center; gap: 6px; min-block-size: 40px;
  min-inline-size: max(40px, calc(var(--kit-pg-d, 2) * 1ch + 20px)); margin: 0; padding: 0 10px; border: 1px solid var(--rule); border-radius: var(--pg-radius, 8px);
  background: var(--panel); color: var(--ink); font: 500 14px/1 var(--f-ui); font-variant-numeric: tabular-nums; text-decoration: none; white-space: nowrap; cursor: pointer; transition: background-color .12s, border-color .12s; }
.kit-pg-btn:hover:not(:disabled):not([aria-disabled="true"]):not(.kit-pg-cur):not(.kit-pg-dots) { border-color: var(--accent); background: var(--accent-soft); }
.kit-pg-cur { border-color: var(--accent); background: var(--accent); color: var(--accent-ink); font-weight: 700; cursor: default; }
.kit-pg-cur::after { content: ""; position: absolute; inset-inline: 30%; inset-block-end: 5px; block-size: 2px; border-radius: 2px; background: currentColor; }
.kit-pg-cur.kit-pg-wordy::after { inset-inline: 14px; }
.kit-pg-btn:disabled, .kit-pg-btn[aria-disabled="true"] { border-style: dashed; border-color: var(--rule-2); background: transparent; color: var(--ink-3); cursor: not-allowed; }
.kit-pg-dots { border-color: transparent; background: transparent; color: var(--ink-3); cursor: default; letter-spacing: .05em; }
.kit-pg-ico { flex: none; inline-size: 16px; block-size: 16px; fill: none; stroke: currentColor; stroke-width: 2.2; stroke-linecap: round; stroke-linejoin: round; }
/* arrows point the reading way: mirrored in a right-to-left page */
.kit-pg-ico:dir(rtl) { transform: scaleX(-1); }
/* First and Last carry their words as accessible names only; long page numbers take the arrows' words away earlier */
.kit-pg-first .kit-pg-t, .kit-pg-last .kit-pg-t { position: absolute; width: 1px; height: 1px; overflow: hidden; clip: rect(0 0 0 0); clip-path: inset(50%); white-space: nowrap; }
.kit-pg-first .kit-pg-arrow, .kit-pg-last .kit-pg-arrow { padding: 0; min-inline-size: 40px; }
.kit-pg-gob { min-inline-size: 40px; }
@container (max-width: 820px) {
  .kit-pg[data-long] .kit-pg-t { position: absolute; width: 1px; height: 1px; overflow: hidden; clip: rect(0 0 0 0); clip-path: inset(50%); white-space: nowrap; }
  .kit-pg[data-long] .kit-pg-arrow { padding: 0; min-inline-size: 40px; }
}
.kit-pg-pick { display: inline-flex; align-items: center; gap: 8px; padding-inline: 6px; }
.kit-pg[data-variant="compact"] .kit-pg-t { position: absolute; width: 1px; height: 1px; overflow: hidden; clip: rect(0 0 0 0); clip-path: inset(50%); white-space: nowrap; }
.kit-pg[data-variant="compact"] .kit-pg-arrow { padding: 0; min-inline-size: 40px; }
.kit-pg[data-variant="load-more"] { justify-items: center; text-align: center; }
.kit-pg-more { display: grid; justify-items: center; gap: 10px; inline-size: 100%; }
.kit-pg-bar { inline-size: min(100%, 320px); block-size: 4px; border-radius: 999px; background: var(--sunk); box-shadow: inset 0 0 0 1px var(--rule); overflow: hidden; }
.kit-pg-fill { display: block; block-size: 100%; inline-size: 0; background: var(--accent); transition: inline-size .3s ease; }
.kit-pg-moreb { gap: 10px; padding: 0 18px; font-weight: 600; white-space: normal; text-align: center; line-height: 1.2; }
.kit-pg-left { color: var(--ink-2); font-weight: 400; }
.kit-pg-left::before { content: "·"; margin-inline-end: 10px; color: var(--ink-3); }
/* numbers read left to right inside a right-to-left sentence; page numbers stay whole */
.kit-pg-num, .kit-pg-cur { unicode-bidi: isolate; }
@container (max-width: 520px) {
  .kit-pg-head { flex-direction: column; align-items: flex-start; }
  .kit-pg-t { position: absolute; width: 1px; height: 1px; overflow: hidden; clip: rect(0 0 0 0); clip-path: inset(50%); white-space: nowrap; }
  .kit-pg-arrow { padding: 0; min-inline-size: 40px; }
}
@container (max-width: 360px) {
  .kit-pg-list { gap: 2px; }
  .kit-pg-btn { min-inline-size: max(32px, calc(var(--kit-pg-d, 2) * 1ch + 12px)); padding: 0 4px; }
  .kit-pg-moreb { padding: 0 12px; }
  .kit-pg-jump { flex-wrap: wrap; }
}
@media (pointer: coarse) {
  .kit-pg-btn, .kit-pg-select, .kit-pg-input { min-block-size: 44px; }
  .kit-pg-btn { min-inline-size: max(44px, calc(var(--kit-pg-d, 2) * 1ch + 20px)); }
  .kit-pg .kit-pg-li .kit-pg-arrow, .kit-pg .kit-pg-jump .kit-pg-gob { min-inline-size: 44px; }
}
@media (prefers-reduced-motion: reduce) { .kit-pg-btn, .kit-pg-fill { transition: none; } }
@media (forced-colors: active) { .kit-pg-cur { forced-color-adjust: none; background: Highlight; color: HighlightText; border-color: Highlight; } .kit-pg-btn[aria-disabled="true"], .kit-pg-btn:disabled { color: GrayText; } }
@media print { .kit-pg-tools, .kit-pg-more { display: none; } }
/* /part:page.style.kit.pagination */

/* part:page.script.kit.pagination */
/**
 * Pagination
 * Kit.pagination.mount(el, opts) draws the paging control under a list of results: a <nav> landmark named "Pagination" holding a list of page links (or buttons), Previous and Next (and optional First and Last), a range summary in words ("Showing 21–40 of 1,234 results"), a page size selector and a "Go to page" field. It returns {get(), set(patch), update(opts), destroy()}. The kit never fetches: it reports onChange(page, {pageSize, reason}) and the page loads the rows.
 *
 * Pattern: the WAI-ARIA APG pagination practice (a navigation landmark with a list; the current page marked aria-current="page"). The current page is not a link: it is a plain element with tabindex="-1", so it is skipped by Tab but focus can be parked on it. Previous and Next at the ends are real disabled controls, out of the tab order and announced as unavailable: in buttons mode a <button disabled>, in links mode an <a> with no href, role="link" and aria-disabled="true" (not focusable, not clickable). They stay in place, so nothing jumps.
 *
 * Truncation: Kit.pagination.pages() keeps the first and last `boundaries` pages and `siblings` pages either side of the current one, joined by gaps. Once the pages do not all fit, the list always has the same number of slots (2*boundaries + 2*siblings + 3), and every page number box is as wide as the widest number, so the Previous and Next buttons do not move while paging. A gap never hides a single page: that page is shown instead.
 *
 * Variants (opts.variant): 'full' (default: numbers, summary, page size, jump), 'compact' ("Page [3] of 12" with a page select between Previous and Next; a typed field above opts.selectMax pages), 'simple' (Previous and Next only, the summary says where you are), 'load-more' (a "Load 20 more · 1,194 left" button, a progress bar and a polite count "Showing 40 of 1,234 results"). opts.responsive true turns 'full' into 'compact' while the kit's own width is under opts.compactBelow (ResizeObserver; the CSS also tightens with a container query).
 * Unknown total (cursor APIs): pass total null (or leave out total and pageCount) and hasNext; the control shows "Page 4" between Previous and Next, no last page, no jump. After Next the page reports the new hasNext through set().
 * Links mode: opts.href(page) -> string (or a template string with {page}) renders real <a href> links with rel prev and next, so the control works without script and with middle-click or Ctrl-click. With onChange a plain click is handled in place (preventDefault) unless opts.navigate is true; without onChange the browser follows the link, and the jump field, the page select and the keys navigate to href(page).
 * Focus after a change: it stays on the control you used when that control still exists and is enabled (Previous, Next, a page number that is still listed, the selects, the jump field, Load more). When it is gone or disabled (you picked page 5, so 5 is now the current page; or Next on the last page) focus moves to the current page marker; in 'simple' to the other arrow; when Load more is used up, to the summary. Nothing moves focus unless focus was already inside the control.
 * Keys: Tab moves through the controls in order. opts.keys true adds, while focus is inside the nav and not in a field: Left and Right for previous and next (mirrored in a right-to-left page), Page Up and Page Down, Home and End for the first and last page.
 * Words: every visible and spoken word is in opts.strings (English by default); {from}, {to}, {total}, {page}, {count}, {min}, {n}, {left}, {shown}, {text} are filled with Intl.NumberFormat numbers for opts.locale (1.234 in de, ١٬٢٣٤ in ar-EG), and strings.results is a word or an Intl.PluralRules map {zero, one, two, few, many, other}.
 *
 * API:
 *   Kit.pagination.mount(el, opts) -> {get(), set(patch), update(opts), destroy(), el}
 *     opts.page          1-based current page (clamped; default 1)
 *     opts.pageCount     number of pages; or opts.total (number of items) with opts.pageSize (default 20). total null = unknown (cursor)
 *     opts.hasNext       with an unknown total: whether there is a next page; opts.hasPrev overrides page > 1
 *     opts.variant       'full' | 'compact' | 'simple' | 'load-more'          opts.responsive true, opts.compactBelow (px, default 480)
 *     opts.siblings      pages each side of the current one (0-5, default 1); opts.boundaries pages kept at each end (0-5, default 1)
 *     opts.firstLast     true adds First and Last controls               opts.summary false hides the visible summary (changes are still announced)
 *     opts.pageSizes     [10, 25, 50, 100] (default) or false; shown in full and compact when the total is known. A change keeps the first visible item on screen.
 *     opts.jump          'auto' (default: when pages are hidden) | true | false            opts.selectMax  compact select up to this many pages (default 1000)
 *     opts.href          (page) => string, or 'path?page={page}'; opts.navigate true lets links navigate even with onChange
 *     opts.keys          true enables the arrow, Page Up/Down, Home and End keys          opts.controlled true: report onChange only; the page calls set()
 *     opts.controls      id of the list the control drives (aria-controls on Load more)
 *     opts.locale, opts.label (the nav's name, default strings.label), opts.strings {label, prev, next, first, last, prevLabel, nextLabel, firstLabel, lastLabel, page, gap, range, rangeOne, rangeOpen, pageOf, pageOnly, none, results, announce, perPage, jump, go, errEmpty, errNaN, errRange, selPage, selOf, selLabel, more, moreOpen, left, shown, shownOpen, done, doneOpen}
 *     opts.onChange      (page, {pageSize, reason, pageCount, total}) after each change made in the control; reason: prev, next, first, last, page, jump, select, size, key, more
 *     handle.get()       {page, pageSize, pageCount, total, from, to, hasNext, hasPrev, variant}   (pageCount and total null when unknown)
 *     handle.set({page, pageCount | total, pageSize, hasNext, hasPrev})   moves the control without onChange; a change of page or total is announced
 *     handle.update(opts) merges any option and redraws;  handle.destroy() removes the markup, the listeners and the ResizeObserver
 *   Kit.pagination.pages(page, pageCount, {siblings, boundaries}) -> [1, 'gap', 4, 5, 6, 'gap', 12]  (pure; bad input is clamped; [] for no pages)
 *
 * First and Last show only their icons (the words are their accessible names); Previous and Next lose their words under 520px of the kit's own width, or 820px when page numbers have five digits or more.
 * Optional custom properties: --pg-radius (corners, default 8px); --kit-pg-d is set by the kit (the width of the widest page number in digits).
 *
 * @id        kit.pagination
 * @kind      component
 * @group     Kit
 * @status    new
 * @version   1.0.0
 * @updated   2026-11-23
 * @summary   Accessible pagination: a nav landmark with stable-width truncation, range summary in words via Intl, page size, go-to-page with errors in words, compact, simple and load-more variants, cursor mode, real links.
 * @tags      pagination, pager, paging, pages, navigation, load more, infinite list, search results, table, cursor, intl, locale, rtl, keyboard, aria
 * @requires  none
 * @files     kit/pagination.css, kit/samples/pagination.json, kit/previews/pagination.js
 * @provides  Kit.pagination.mount, Kit.pagination.pages
 * @config    Kit.pagination.mount(el, opts) | page, pageCount or total with pageSize, hasNext, variant, responsive, siblings, boundaries, firstLast, pageSizes, jump, href, keys, controlled, locale, strings, onChange(page, {pageSize, reason}); returns {get, set, update, destroy}
 * @config    Kit.pagination.pages(page, pageCount, {siblings, boundaries}) | page numbers and 'gap' tokens, same length while truncated
 * @tokens    --panel --sunk --ink --ink-2 --ink-3 --rule --rule-2 --accent --accent-ink --accent-soft --danger --danger-soft --f-ui --focus? --pg-radius? --kit-pg-d?
 * @globals   none
 * @db        note None. The control keeps no data; onChange reports each change and the page loads and keeps what it wants.
 * @source    Written for this catalog | kit/pagination.js | first version
 * @preview   {"render": "kit.pagination", "samples": ["kit/samples/pagination.json"]}
 * @changed   First version.
 */
(function () {
'use strict';
const Kit = window.Kit = window.Kit || { version: '0.1.0' };
let seq = 0;

const WORDS = {
  label: 'Pagination', prev: 'Previous', next: 'Next', first: 'First', last: 'Last',
  prevLabel: 'Previous page', nextLabel: 'Next page', firstLabel: 'First page', lastLabel: 'Last page',
  page: 'Page {page}', gap: 'More pages',
  range: 'Showing {from}–{to} of {total} {results}', rangeOne: 'Showing {from} of {total} {results}', rangeOpen: 'Showing {from}–{to}',
  pageOf: 'Page {page} of {count}', pageOnly: 'Page {page}', none: 'No results', results: { one: 'result', other: 'results' },
  announce: '{page}. {summary}',
  perPage: 'Per page', jump: 'Go to page', go: 'Go',
  errEmpty: 'Type a page number.', errNaN: '“{text}” is not a page number.', errRange: 'Choose a page from {min} to {count}.',
  selPage: 'Page', selOf: 'of {count}', selLabel: 'Page, of {count}',
  more: 'Load {n} more', moreOpen: 'Load more', left: '{left} left',
  shown: 'Showing {shown} of {total} {results}', shownOpen: 'Showing {shown} {results}',
  done: 'All {total} {results} shown', doneOpen: 'All {shown} {results} shown'
};
const VARIANTS = ['full', 'compact', 'simple', 'load-more'];
const MAX = Number.MAX_SAFE_INTEGER;

// ---------------------------------------------------------------- pure helpers
function int(v, d) {
  const n = typeof v === 'number' ? v : typeof v === 'string' && v.trim() !== '' ? Number(v) : NaN;
  return Number.isFinite(n) ? Math.trunc(n) : d;
}
const clamp = (n, a, b) => Math.min(b, Math.max(a, n));
const seqOf = (a, b) => { const out = []; for (let i = a; i <= b; i++) out.push(i); return out; };
const fill = (t, v) => String(t == null ? '' : t).replace(/\{(\w+)\}/g, (m, k) => (k in v ? v[k] : m));

/** Page numbers and 'gap' tokens for a pager. Same length (2b + 2s + 3) whenever pages are hidden; a gap always hides two or more pages. */
function pages(page, pageCount, o) {
  o = o || {};
  const count = clamp(int(pageCount, 0), 0, MAX);
  if (count < 1) return [];
  const p = clamp(int(page, 1), 1, count);
  const s = clamp(int(o.siblings, 1), 0, 5), b = clamp(int(o.boundaries, 1), 0, 5);
  if (count <= 2 * b + 2 * s + 3) return seqOf(1, count);
  const from = Math.max(Math.min(p - s, count - b - 2 * s - 1), b + 2);
  const to = Math.min(Math.max(p + s, b + 2 * s + 2), count - b - 1);
  const out = seqOf(1, b);
  if (from > b + 2) out.push('gap'); else if (b + 1 < count - b) out.push(b + 1);
  out.push(...seqOf(from, to));
  if (to < count - b - 1) out.push('gap'); else if (count - b > b) out.push(count - b);
  out.push(...seqOf(count - b + 1, count));
  return out;
}

// digits people may type: Arabic-Indic, Persian, full-width
function asciiDigits(t) {
  return t.replace(/[٠-٩]/g, c => c.charCodeAt(0) - 0x660).replace(/[۰-۹]/g, c => c.charCodeAt(0) - 0x6F0)
    .replace(/[０-９]/g, c => c.charCodeAt(0) - 0xFF10);
}

const ICON = { prev: 'M15 5l-7 7 7 7', next: 'M9 5l7 7-7 7', first: 'M17 5l-7 7 7 7M8 5v14', last: 'M7 5l7 7-7 7M16 5v14' };
function icon(kind) {
  const NS = 'http://www.w3.org/2000/svg';
  const svg = document.createElementNS(NS, 'svg');
  svg.setAttribute('viewBox', '0 0 24 24'); svg.setAttribute('aria-hidden', 'true'); svg.setAttribute('focusable', 'false');
  svg.setAttribute('class', 'kit-pg-ico');
  const path = document.createElementNS(NS, 'path'); path.setAttribute('d', ICON[kind]); svg.append(path);
  return svg;
}
function mk(tag, cls, attrs, text) {
  const e = document.createElement(tag);
  if (cls) e.className = cls;
  for (const k in attrs || {}) if (attrs[k] != null && attrs[k] !== false) e.setAttribute(k, attrs[k] === true ? '' : attrs[k]);
  if (text != null) e.textContent = text;
  return e;
}

// ---------------------------------------------------------------- mount
function mount(el, opts) {
  if (!el || el.nodeType !== 1) throw new TypeError('Kit.pagination.mount(el, opts): el must be an element');
  const uid = 'kit-pg-' + (++seq);
  const o = Object.assign({}, opts || {});
  let st = null, narrow = false, ro = null, liveTimer = 0, errTimer = 0, roFrame = 0, dead = false;
  let W = WORDS, nf = null, pr = null;

  const root = mk('div', 'kit-pg');
  const head = mk('div', 'kit-pg-head');
  const sum = mk('p', 'kit-pg-sum', { id: uid + '-sum', tabindex: '-1' });
  const tools = mk('div', 'kit-pg-tools');
  const sizeBox = mk('label', 'kit-pg-size');
  const sizeT = mk('span', 'kit-pg-lbl');
  const sizeSel = mk('select', 'kit-pg-select', { 'data-k': 'size' });
  sizeBox.append(sizeT, sizeSel);
  const jumpF = mk('form', 'kit-pg-jump', { novalidate: true, 'data-role': 'jump' });
  const jumpL = mk('label', 'kit-pg-lbl', { for: uid + '-jump' });
  const jumpIn = mk('input', 'kit-pg-input', { id: uid + '-jump', type: 'text', inputmode: 'numeric', autocomplete: 'off', enterkeyhint: 'go', spellcheck: 'false', 'data-k': 'jumpin', 'aria-describedby': uid + '-err' });
  const jumpB = mk('button', 'kit-pg-btn kit-pg-gob', { type: 'submit', 'data-k': 'gob' });
  jumpF.append(jumpL, jumpIn, jumpB);
  tools.append(sizeBox, jumpF);
  head.append(sum, tools);
  const nav = mk('nav', 'kit-pg-nav');
  const list = mk('ul', 'kit-pg-list');
  nav.append(list);
  const err = mk('p', 'kit-pg-err', { id: uid + '-err', 'aria-live': 'assertive' });
  const more = mk('div', 'kit-pg-more');
  const bar = mk('div', 'kit-pg-bar', { 'aria-hidden': 'true' });
  const barFill = mk('span', 'kit-pg-fill');
  bar.append(barFill);
  const moreB = mk('button', 'kit-pg-btn kit-pg-moreb', { type: 'button', 'data-k': 'more' });
  const moreT = mk('span', 'kit-pg-moret'), moreLeft = mk('span', 'kit-pg-left');
  moreB.append(moreT, moreLeft);
  more.append(bar, moreB);
  const live = mk('p', 'kit-pg-sr', { 'aria-live': 'polite', 'aria-atomic': 'true' });
  root.append(head, nav, err, more, live);
  el.append(root);

  // ---- settings
  function words() {
    W = Object.assign({}, WORDS, o.strings && typeof o.strings === 'object' ? o.strings : null);
    let loc = o.locale || (el.closest('[lang]') && el.closest('[lang]').lang) || (typeof navigator !== 'undefined' && navigator.language) || 'en';
    try { nf = new Intl.NumberFormat(loc); pr = new Intl.PluralRules(loc); } catch (e) { nf = new Intl.NumberFormat('en'); pr = new Intl.PluralRules('en'); }
  }
  const N = n => nf.format(n);
  const resultsWord = n => { const r = W.results; if (r == null) return ''; if (typeof r !== 'object') return String(r); return r[pr.select(n)] != null ? r[pr.select(n)] : (r.other || ''); };
  const links = () => o.href != null && o.href !== false && o.href !== '';
  const intercept = () => links() && typeof o.onChange === 'function' && !o.navigate;
  function hrefOf(p) {
    let h = typeof o.href === 'function' ? o.href(p) : String(o.href).replace(/\{page\}/g, p);
