    else if (st.total != null) { from = st.from; to = st.to; }
    else if (st.pageCount !== 0) { from = (st.page - 1) * st.pageSize + 1; to = st.page * st.pageSize; }
  }
  const cap = st && st.variant === 'load-more' ? 24 : 12;
  const loc = s.opts && s.opts.locale;
  const nf = new Intl.NumberFormat(loc || undefined);
  const shownFrom = st && st.variant === 'load-more' ? Math.max(from, to - cap + 1) : from;
  const items = [];
  for (let n = shownFrom; n >= 1 && n <= to && items.length < cap; n++) items.push(n);
  const rest = to - from + 1 - items.length;
  return html`<div class="pv-stack"><style>${CSS}</style>
    <div class="pv-row" role="group" aria-label="Sample"><span class="pv-label">Sample</span>${d.samples.map(x => pick([x.key, x.label], setKey, key))}</div>
    ${!s.width && html`<div class="pv-row" role="group" aria-label="Frame width"><span class="pv-label">Frame</span>${[['full', 'Full width'], ['phone', '360 px']].map(x => pick(x, setW, w))}</div>`}
    <p class="pv-sim"><b>Sandbox</b> ${s.about} The kit never fetches: the preview invents the items for whatever page onChange reports.</p>
    <div class="pv-pg-box" style=${'max-width:' + width} dir=${s.dir || null} lang=${s.lang || null}>
      <div key="items" class="pv-pg-list">${to >= from && to > 0
        ? [rest > 0 && st && st.variant === 'load-more' && html`<p key="before" class="pv-pg-more">… ${nf.format(rest)} earlier items</p>`,
          html`<ol key="ol" class="pv-pg-items" id="pv-pg-items">${items.map(n => html`<li key=${n}><b>${nf.format(n)}</b><span>${title(n)}</span></li>`)}</ol>`,
          rest > 0 && st && st.variant !== 'load-more' && html`<p key="after" class="pv-pg-more">… and ${nf.format(rest)} more on this page</p>`]
        : html`<p key="none" class="pv-pg-empty">Nothing matched.</p>`}</div>
      <div key="host" ref=${host}></div>
    </div>
    <p class="pv-pg-log" aria-live="off">${st ? 'get() ' + JSON.stringify(st) : ''}${'\n'}${log.length ? 'onChange\n' + log.join('\n') : 'onChange: no change yet'}</p>
  </div>`;
};
})();
